import{_ as e}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o,c as d,a as r}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const f=JSON.parse('{"title":"Keyboard shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"reference/keyboard-shortcuts.md","filePath":"reference/keyboard-shortcuts.md"}'),a={name:"reference/keyboard-shortcuts.md"};function c(n,t,i,s,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>All shortcuts are active in the interactive TUI. Keys are <strong>case-sensitive</strong> — most use lowercase letters, but a few bindings (such as <code>Z</code> and <code>G</code>) require an uppercase letter.</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>k</code></td><td>Move cursor up (repos and extracts)</td></tr><tr><td><code>↓</code> / <code>j</code></td><td>Move cursor down (repos and extracts)</td></tr><tr><td><code>←</code></td><td>Fold the repo under the cursor</td></tr><tr><td><code>→</code></td><td>Unfold the repo under the cursor</td></tr><tr><td><code>Z</code></td><td><strong>Global fold / unfold</strong> — fold all repos if any is unfolded; unfold all if all are folded</td></tr><tr><td><code>gg</code></td><td>Jump to the <strong>top</strong> (first result)</td></tr><tr><td><code>G</code></td><td>Jump to the <strong>bottom</strong> (last result)</td></tr><tr><td><code>Page Up</code> / <code>Ctrl+U</code></td><td>Scroll up one full page</td></tr><tr><td><code>Page Down</code> / <code>Ctrl+D</code></td><td>Scroll down one full page</td></tr></tbody></table><p>Section header rows (shown when <code>--group-by-team-prefix</code> is active) are skipped automatically during navigation.</p><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Space</code></td><td>Toggle selection on the current repo or extract. On a repo row: cascades to all its extracts.</td></tr><tr><td><code>a</code></td><td>Select <strong>all</strong>. On a repo row: selects all repos and their extracts. On an extract row: selects all extracts in the current repo. Respects active filters.</td></tr><tr><td><code>n</code></td><td>Select <strong>none</strong>. Same context rules as <code>a</code>. Respects active filters.</td></tr><tr><td><code>o</code></td><td><strong>Open in browser</strong> — opens the focused item in the default browser. On a repo row: opens the repository page. On an extract row: opens the file directly.</td></tr></tbody></table><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>f</code></td><td>Open the filter bar and enter filter mode</td></tr><tr><td><code>t</code></td><td>Cycle the <strong>filter target</strong>: <code>path</code> → <code>content</code> → <code>repo</code> → <code>path</code>. Only works <strong>outside</strong> filter mode and when <strong>not</strong> on a picked repo (see <a href="#team-ownership">Team ownership</a> below).</td></tr><tr><td><code>r</code></td><td>Reset the active filter and return to showing all repos / extracts</td></tr></tbody></table><h3 id="filter-targets" tabindex="-1">Filter targets <a class="header-anchor" href="#filter-targets" aria-label="Permalink to &quot;Filter targets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Target</th><th>What is matched</th><th>Shown / hidden unit</th></tr></thead><tbody><tr><td><code>path</code></td><td>File path substring (default). Case-insensitive.</td><td>Individual extracts</td></tr><tr><td><code>content</code></td><td>Code fragment text (the snippet returned by GitHub Search). Case-insensitive.</td><td>Individual extracts</td></tr><tr><td><code>repo</code></td><td>Repository full name (<code>org/repo</code>). Case-insensitive.</td><td>Entire repo + extracts</td></tr></tbody></table><p>The active target is always shown in the filter bar badge: <code>[path]</code>, <code>[content]</code>, or <code>[repo]</code> (with <code>·regex</code> appended when regex mode is on).</p><h3 id="filter-mode-bindings" tabindex="-1">Filter mode bindings <a class="header-anchor" href="#filter-mode-bindings" aria-label="Permalink to &quot;Filter mode bindings&quot;">​</a></h3><p>When the filter bar is open (after pressing <code>f</code>):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td>Printable characters / paste</td><td>Insert character(s) at the cursor position</td></tr><tr><td><code>←</code> / <code>→</code></td><td>Move the text cursor one character left / right</td></tr><tr><td><code>⌥←</code> / <code>⌥→</code> (macOS) · <code>Ctrl+←</code> / <code>Ctrl+→</code> · <code>Alt+b</code> / <code>Alt+f</code></td><td>Jump one word left / right</td></tr><tr><td><code>Backspace</code></td><td>Delete the character before the cursor</td></tr><tr><td><code>⌥⌫</code> (macOS) · <code>Ctrl+W</code></td><td>Delete the word before the cursor</td></tr><tr><td><code>Tab</code></td><td>Toggle <strong>regex</strong> mode (badge shows <code>[…·regex]</code> when on)</td></tr><tr><td><code>Shift+Tab</code></td><td>Cycle the <strong>filter target</strong> (<code>path</code> → <code>content</code> → <code>repo</code> → <code>path</code>)</td></tr><tr><td><code>Enter</code></td><td>Confirm the filter and apply it</td></tr><tr><td><code>Esc</code></td><td>Cancel without applying the filter</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Invalid regex patterns do not crash the TUI but are treated as matching nothing (zero visible rows). The badge is always yellow when regex mode is active, regardless of whether the pattern is valid.</p></div><h2 id="team-ownership" tabindex="-1">Team ownership <a class="header-anchor" href="#team-ownership" aria-label="Permalink to &quot;Team ownership&quot;">​</a></h2><p>Available only when <code>--group-by-team-prefix</code> is active.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>p</code></td><td>On a <strong>multi-team</strong> section header: enter team pick mode to assign the section to a single owner. Does nothing on single-team section headers.</td></tr><tr><td><code>t</code></td><td>On a <strong>picked repo</strong> (marked <code>◈</code>, moved by a previous pick): enter re-pick mode to change its team assignment or restore it to the combined section.</td></tr></tbody></table><h3 id="pick-mode-bindings" tabindex="-1">Pick mode bindings <a class="header-anchor" href="#pick-mode-bindings" aria-label="Permalink to &quot;Pick mode bindings&quot;">​</a></h3><p>When pick mode is active (after pressing <code>p</code> on a multi-team section header):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> / <code>→</code></td><td>Move focus between candidate teams (highlighted / dimmed)</td></tr><tr><td><code>Enter</code></td><td>Confirm the pick and exit pick mode</td></tr><tr><td><code>Esc</code></td><td>Cancel and exit pick mode without changes</td></tr></tbody></table><h3 id="re-pick-mode-bindings" tabindex="-1">Re-pick mode bindings <a class="header-anchor" href="#re-pick-mode-bindings" aria-label="Permalink to &quot;Re-pick mode bindings&quot;">​</a></h3><p>When re-pick mode is active (after pressing <code>t</code> on a picked repo marked <code>◈</code>):</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> / <code>→</code></td><td>Cycle through candidate teams (from the original combined section label)</td></tr><tr><td><code>Enter</code></td><td>Confirm and move the repo to the focused candidate team</td></tr><tr><td><code>0</code> / <code>u</code></td><td>Undo the entire section pick — restore all repos from that combined section to their original label</td></tr><tr><td><code>Esc</code> / <code>t</code></td><td>Exit re-pick mode without changes</td></tr></tbody></table><h2 id="help-and-exit" tabindex="-1">Help and exit <a class="header-anchor" href="#help-and-exit" aria-label="Permalink to &quot;Help and exit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>h</code> / <code>?</code></td><td>Toggle the help overlay (shows all key bindings)</td></tr><tr><td><code>Enter</code></td><td>When help overlay is <strong>closed</strong>: confirm and print selected results. When <strong>open</strong>: close the overlay.</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Quit without printing results</td></tr></tbody></table><h2 id="mouse-support" tabindex="-1">Mouse support <a class="header-anchor" href="#mouse-support" aria-label="Permalink to &quot;Mouse support&quot;">​</a></h2><p>The interactive TUI supports mouse interaction via the terminal&#39;s SGR (Select-Graphic-Rendition) mouse protocol, enabling click-based navigation and selection alongside keyboard shortcuts.</p><h3 id="scroll-wheel" tabindex="-1">Scroll wheel <a class="header-anchor" href="#scroll-wheel" aria-label="Permalink to &quot;Scroll wheel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Scroll up / down wheel</td><td>Scroll the viewport up or down by 3 rows</td></tr><tr><td>Scroll during momentum</td><td>Clicks are ignored during trackpad momentum scrolling</td></tr></tbody></table><p>During trackpad momentum scrolling (macOS, Linux), the TUI enters a brief &quot;scroll cooldown&quot; period to ignore accidental clicks while the scroll is still decelerating. This prevents unintended selections.</p><h3 id="click-actions" tabindex="-1">Click actions <a class="header-anchor" href="#click-actions" aria-label="Permalink to &quot;Click actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Single-click on row</strong> (anywhere)</td><td>Move the cursor to that row (navigation)</td></tr><tr><td><strong>Double-click on row</strong></td><td>Perform the double-click action for that row type (see below)</td></tr><tr><td><strong>Double-click on fold icon</strong> (▸/▾, repo rows)</td><td>Toggle repo fold state (show/hide extracts)</td></tr><tr><td><strong>Double-click on checkbox or row content</strong> (repos)</td><td>Toggle the repo&#39;s selection state (cascades to all extracts)</td></tr><tr><td><strong>Double-click on checkbox or row content</strong> (extracts)</td><td>Toggle that extract&#39;s selection state</td></tr></tbody></table><h3 id="click-zones" tabindex="-1">Click zones <a class="header-anchor" href="#click-zones" aria-label="Permalink to &quot;Click zones&quot;">​</a></h3><p>The TUI divides each row into interactive zones:</p><p><strong>Repo rows</strong> (<code>&quot;▸ ✓ repo-name&quot;</code>):</p><table tabindex="0"><thead><tr><th>Zone</th><th>Columns</th><th>Action on double-click</th></tr></thead><tbody><tr><td>Fold control</td><td>1–2</td><td>Toggle fold (show/hide extracts)</td></tr><tr><td>Checkbox zone</td><td>4+</td><td>Toggle repo selection (full-width double)</td></tr><tr><td>Navigation</td><td>3</td><td>Single-click only (move cursor)</td></tr></tbody></table><p><strong>Extract rows</strong> (<code>&quot; ✓ path:line:col&quot;</code>):</p><table tabindex="0"><thead><tr><th>Zone</th><th>Columns</th><th>Action on double-click</th></tr></thead><tbody><tr><td>Indent</td><td>1–3</td><td>Single-click only (move cursor)</td></tr><tr><td>Checkbox zone</td><td>4+</td><td>Toggle extract selection (full-width)</td></tr></tbody></table><p>Note: All double-click actions are mapped to the row type (repo or extract) and the click column. Clicking anywhere from column 4 onwards (checkbox start) triggers a selection action; clicking on columns 1–3 only triggers navigation or fold (repo rows only).</p><h3 id="relationship-with-keyboard" tabindex="-1">Relationship with keyboard <a class="header-anchor" href="#relationship-with-keyboard" aria-label="Permalink to &quot;Relationship with keyboard&quot;">​</a></h3><p>Mouse and keyboard shortcuts are fully complementary:</p><ul><li><strong>Selection</strong>: Mouse double-click on checkbox = Spacebar <code>Space</code></li><li><strong>Navigation</strong>: Mouse single-click = Arrow keys <code>↑</code> / <code>↓</code></li><li><strong>Fold control</strong>: Mouse double-click on fold icon = Arrow keys <code>←</code> / <code>→</code></li><li><strong>Select all / Select none</strong>: Keyboard <code>a</code> / <code>n</code> (no mouse equivalent)</li></ul>',44)])])}const k=e(a,[["render",c]]);export{f as __pageData,k as default};
